const mime = (to, sujet, corps, extra = []) => b64url([...(to ? ['To: ' + to] : []), ...extra, 'Subject: =?UTF-8?B?' + Buffer.from(sujet).toString('base64') + '?=', 'MIME-Version: 1.0', 'Content-Type: text/plain; charset="UTF-8"', 'Content-Transfer-Encoding: base64', '', Buffer.from(corps).toString('base64')].join('\r\n'));

const carte = $('Carte Pipedrive').first().json; const K = carte.deal, KP = carte.person;
const d = $('À scorer').item.json; const p = $('Lire personne').item.json.data || {};
const B = {
  signal: { 'plateforme de marque / repositionnement / identite': 25, 'lancement ou campagne a venir': 22, "nomination d'un decideur": 20, 'acceleration ia / contenus': 18, 'ouverture ou renovation de lieu': 15, "appel d'offres": 12, 'autre signal': 5 },
  adequation: { 'strategie, creation et ia': 20, 'direction creative ou image': 15, 'ia generative seule': 12, 'editorial ou social': 8, 'aucune': 0 },
  niveau: { 'direction': 15, 'head / vp': 12, 'manager': 8, 'chef de projet': 4, 'hors cible': 0 },
  secteur: { 'beaute & parfumerie': 10, 'joaillerie & horlogerie': 10, 'mode & maroquinerie': 10, 'vins & spiritueux': 8, 'hospitality & lifestyle': 8, 'lifestyle premium': 6, 'prescripteurs': 6 },
  taille: { '50 m€ a 1 md€ ou direction de marque propre': 10, 'groupe sans porte d\'entree identifiee': 6, '10 a 50 m€': 5, 'moins de 10 m€': 2 },
  porte: { 'lien reseau, ancien client ou recommandation': 10, 'interaction linkedin ou evenement commun': 6, 'aucune': 2 }
};
const f = { type: val(d, K['Type de signal']), date: val(d, K['Date de publication']), adeq: val(d, K['Adéquation expertises']), niveau: val(p, KP['Niveau de décision']), cat: val(d, K['Catégorie']), taille: val(d, K['Taille budget']), porte: val(d, K["Porte d'entrée"]) };
const age = /^\d{4}-\d{2}-\d{2}/.test(f.date || '') ? Math.max(0, Math.floor((Date.now() - new Date(f.date).getTime()) / 864e5)) : null;
const inconnus = []; const lignes = [];
const pts = (bar, v, lab) => { if (!v) return 0; const x = B[bar][norm(v)]; if (x === undefined) { inconnus.push(lab + ' « ' + v + ' »'); return 0; } return x; };
const add = (lab, v, max) => { lignes.push(lab + ' : ' + v + '/' + max); return v; };
let sig = pts('signal', f.type, 'Type de signal');
if (norm(f.type).startsWith('nomination') && age !== null && age > 90) sig = 5;   // nomination de plus de 90 jours
let s = 0;
s += add('1. Signal déclencheur (' + (f.type || 'aucun') + ')', sig, 25);
s += add('2. Adéquation avec les expertises (' + (f.adeq || 'non renseignée') + ')', pts('adequation', f.adeq, 'Adéquation expertises'), 20);
s += add('3. Niveau de décision (' + (f.niveau || 'non renseigné') + ')', pts('niveau', f.niveau, 'Niveau de décision'), 15);
s += add('4. Secteur (' + (f.cat || 'non renseigné') + ')', pts('secteur', f.cat, 'Catégorie'), 10);
s += add('5. Taille et budget (' + (f.taille || 'non renseigné') + ')', pts('taille', f.taille, 'Taille budget'), 10);
s += add('6. Fraîcheur (' + (age === null ? 'date inconnue' : age + ' jours') + ')', age === null ? 0 : age < 7 ? 10 : age <= 30 ? 7 : age <= 90 ? 4 : 0, 10);
s += add("7. Porte d'entrée (" + (f.porte || 'aucune') + ')', f.porte ? pts('porte', f.porte, "Porte d'entrée") : 2, 10);
const niveau = s >= 75 ? 'A · Priorité' : s >= 55 ? 'B · Réserve' : s >= 35 ? 'C · Veille' : 'Archivé';
const action = s >= 75 ? "Présenter à l'arbitrage du lundi ; message préparé dans la semaine" : s >= 55 ? 'Activer si le plafond hebdomadaire le permet' : s >= 35 ? 'Aucune action ; rescoring au prochain signal' : 'Conserver sans action ; suppression selon la durée de conservation';
const fonction = fonctionDe(val(p, KP['Poste']));
const angle = ANGLES[fonction] || ANGLES.Marketing;
const motif = [f.type ? f.type + (age !== null ? ' il y a ' + age + ' jours' : '') : 'aucun signal daté', f.adeq ? 'besoin probable : ' + f.adeq.toLowerCase() : null, f.niveau ? 'décideur : ' + f.niveau : null, 'porte d\'entrée : ' + (f.porte || 'aucune')].filter(Boolean).join(' · ') + '.';
const body = { [K['Score Résonance']]: String(s), [K['Détail du score']]: lignes.join(' | ') + (inconnus.length ? ' | Valeurs non reconnues : ' + inconnus.join(', ') : ''), [K['Motif du score']]: motif, [K['Niveau']]: niveau, [K['Prochaine action']]: action };
if (!val(d, K['Angle'])) body[K['Angle']] = angle;
if (niveau === 'Archivé') body.stage_id = carte.stage['En pause'];
const note_html = '<b>Score Résonance (agent 3) : ' + s + '/100 · ' + niveau + '</b><br>' + lignes.map(esc).join('<br>') + '<br><b>Motif :</b> ' + esc(motif) + '<br><b>Angle recommandé :</b> ' + esc(angle) + ' (fonction ' + fonction + ')<br><b>Prochaine action :</b> ' + esc(action) +
  (inconnus.length ? '<br><b>Valeurs non reconnues :</b> ' + esc(inconnus.join(', ')) : '') + '<br><i>Calculé par code. Pour corriger : modifier les champs puis vider « Score Résonance » ; noter le motif de la correction.</i>';
return { json: { deal_id: d.id, body, note_html } };
